using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps;
public static class Lantern169BudgetChecks{
 [Serializable]class Row{public string name;public bool pass;public int finalLights;public string[] issues;}
 [Serializable]class Report{public bool pass;public string baseline="e653493505bda4a61220828616832cb445583760";public Row[] cases;}
 public static void Baseline()=>RunAll("before");public static void Run()=>RunAll("after");
 static void RunAll(string phase){string dir=Path.Combine(Path.GetDirectoryName(Application.dataPath),"Evidence169");Directory.CreateDirectory(dir);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rows=new List<Row>();foreach(var name in new[]{"exact-0-45-100","reverse-20-minus25-minus100","unequal-gains","variable-dt","disable-during-transfer","budget-disable-enable"}){var root=new GameObject(name);var fs=new List<RoomTorchInstance>();foreach(float x in new[]{0f,20f}){var go=new GameObject("lamp"+x);go.transform.SetParent(root.transform);go.transform.position=new Vector3(x,1.65f,0);var f=go.AddComponent<RoomTorchInstance>();f.ConfigureLamp(Vector3.zero,3.2f,5.5f,go.name);fs.Add(f);}var b=root.AddComponent<RoomTorchBudget>();b.Configure(fs.ToArray());bool reverse=name.StartsWith("reverse");var issues=new List<string>();Action<float,int> tick=(x,n)=>{for(int j=0;j<n;j++){float dt=name=="variable-dt"?(j%3==0?.1f:j%3==1?.01f:.025f):1/30f;b.Tick(dt,new Vector3(x,0,0));if(root.GetComponentsInChildren<Light>().Count(l=>l.enabled)>2)issues.Add("more than two lights");}};
 tick(reverse?20:0,120);if(fs.Any(f=>f.SourceLight==null||!f.SourceLight.enabled))issues.Add("initial pair not lit");if(name=="unequal-gains"){var gains=(float[])typeof(RoomTorchBudget).GetField("gains",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(b);gains[0]=.95f;gains[1]=.12f;}
 tick(reverse?-25:45,12);if(name=="disable-during-transfer")fs[reverse?0:1].gameObject.SetActive(false);if(name=="budget-disable-enable"){b.enabled=false;b.SendMessage("OnDisable");if(root.GetComponentsInChildren<Light>().Any(l=>l.enabled))issues.Add("budget disabled light remains");b.enabled=true;b.SendMessage("OnEnable");}
 tick(reverse?-25:45,150);var survivor=fs[reverse?0:1];if(survivor.gameObject.activeSelf&&(survivor.SourceLight==null||!survivor.SourceLight.enabled))issues.Add("destination lamp not lit");var active=root.GetComponentsInChildren<Light>().Where(l=>l.enabled).ToArray();if(active.Length!=(survivor.gameObject.activeSelf?1:0))issues.Add("settled wrong light count "+active.Length);if(survivor.gameObject.activeSelf&&active.Any(l=>Vector3.Distance(l.transform.position,survivor.transform.position)>.01f))issues.Add("light remains at old owner");
 tick(reverse?-100:100,150);int final=root.GetComponentsInChildren<Light>().Count(l=>l.enabled);if(final!=0)issues.Add("final orphan lights "+final);foreach(var f in fs)f.gameObject.SetActive(false);tick(0,150);if(root.GetComponentsInChildren<Light>().Any(l=>l.enabled))issues.Add("disabled fixture light remains");rows.Add(new Row{name=name,pass=issues.Count==0,finalLights=final,issues=issues.Distinct().ToArray()});UnityEngine.Object.DestroyImmediate(root);}
 var report=new Report{pass=rows.All(r=>r.pass),cases=rows.ToArray()};File.WriteAllText(Path.Combine(dir,"budget-"+phase+".json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(phase=="before"||report.pass?0:1);
 }catch(Exception e){File.WriteAllText(Path.Combine(dir,"error-"+phase+".txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
